from html.parser import HTMLParser

class P(HTMLParser):
    def handle_starttag(self, tag, attrs):
        print("START", repr(tag), attrs, repr(self.get_starttag_text()))
    def handle_startendtag(self, tag, attrs):
        print("STARTEND", repr(tag), attrs, repr(self.get_starttag_text()))
    def handle_endtag(self, tag):
        print("END", repr(tag))
    def handle_data(self, data):
        print("DATA", repr(data))
    def error(self, msg):
        print("ERROR", msg)

for t in ['<svg/onload=alert(1)>', '<svg / onload=alert(1)>', '<svg/onload="alert(1)"/>', '<img/src=x/onerror=alert(1)>']:
    print("="*20, repr(t))
    p = P(convert_charrefs=False)
    try:
        p.feed(t)
        p.close()
    except Exception as e:
        print("EXC:", e)
